function combinationSum(candidates, target) {
  const sorted = [...candidates].sort((a, b) => a - b);   // sorting lets us prune early
  const result = [];
  const current = [];

  function explore(start, remaining) {
    if (remaining === 0) {                 // exact hit: record a copy
      result.push([...current]);
      return;
    }
    for (let i = start; i < sorted.length; i++) {
      if (sorted[i] > remaining) break;    // prune: this and every bigger candidate overshoot
      current.push(sorted[i]);             // choose
      explore(i, remaining - sorted[i]);   // explore: i, not i + 1, because reuse is allowed
      current.pop();                       // un-choose
    }
  }

  explore(0, target);
  return result;
}

