function norm(lists) { return lists.map((l) => [...l].sort((a, b) => a - b)).map((l) => JSON.stringify(l)).sort(); }
assertEqual(norm(combinationSum([5], 5)), norm([[5]]));
assertEqual(norm(combinationSum([3], 9)), norm([[3,3,3]]));

function norm(lists) { return lists.map((l) => [...l].sort((a, b) => a - b)).map((l) => JSON.stringify(l)).sort(); }
const got = combinationSum([7,3,2], 12);
assertEqual(norm(got), norm([[2,2,2,2,2,2],[2,2,2,3,3],[3,3,3,3],[2,3,7]]));
assertEqual(new Set(norm(got)).size, got.length, 'each combination should appear once');

const got = combinationSum([2,3,5], 10);
assertEqual(got.length, 4);
assert(got.every((c) => c.reduce((s, x) => s + x, 0) === 10), 'every combination must sum to 10');
